-- Stałe trasy jednostek NPC: ruch w tle widoczny na radarze okrętów gracza.
--
-- Każda jednostka kursuje między dwoma portami (planety z mapa_planety, po nazwie) w stałym cyklu:
-- postój w porcie A → lot do punktu skoku (w stronę celu) → nadprzestrzeń (niewidoczna) → dolot z punktu
-- wyjścia do portu B → postój → i z powrotem. Fazę liczy serwer z czasu (api/radar.php, radar_tlo), więc każda
-- jednostka jest w innym miejscu trasy. rejestr = 0: lata bez transpondera (trasę i ładunek ujawnia dopiero
-- analiza sygnatury). Gęstość według regionu: Głębokie Jądro i huby handlowe (Kuat, Coruscant, Corellia…)
-- najgęściej; sektor Hune pomija serwer.
--
-- Wygenerowane skryptem. Import w phpMyAdmin; ponowny import czyści i wpisuje trasy od nowa.

USE hololink;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS npc_trasy (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  nazwa VARCHAR(80) NOT NULL,
  klasa VARCHAR(80) NOT NULL DEFAULT '',
  port_a VARCHAR(120) NOT NULL,
  port_b VARCHAR(120) NOT NULL,
  ladunek VARCHAR(120) NOT NULL DEFAULT '',
  frakcja ENUM('Imperium','Rebelia','Syndykat','neutralna') NULL,
  rejestr TINYINT(1) NOT NULL DEFAULT 1 COMMENT '1 = nadaje prawdziwy transponder',
  predkosc_au_h DECIMAL(5,2) NOT NULL DEFAULT 1.50 COMMENT 'prędkość podświetlna w układzie',
  postoj_h DECIMAL(5,1) NOT NULL DEFAULT 6.0 COMMENT 'postój w każdym porcie',
  faza DECIMAL(5,4) NOT NULL DEFAULT 0 COMMENT 'przesunięcie cyklu (0–1)',
  aktywna TINYINT(1) NOT NULL DEFAULT 1,
  KEY ix_npc_trasy_a (port_a),
  KEY ix_npc_trasy_b (port_b)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM npc_trasy;
































